const classifyTaskDB=[{"w":"La actio","gen":"Tratado clásico de oratoria","n":"La ejecución de pie con voz y gesto","g":"Retórica clásica","t":"Quintiliano, hacia 95 d.C."},{"w":"La composición oral","gen":"Teoría de la épica oral, con trabajo de campo","n":"El poeta oral compone en vivo con fórmulas","g":"Estudios orales","t":"Parry y Lord, 1960"},{"w":"La oralidad","gen":"Tesis fuerte de un estudioso","n":"El pensamiento oral es distinto del escrito","g":"Teoría de la comunicación","t":"Ong, 1982"},{"w":"El efecto Kuleshov","gen":"Experimento clásico del cine (con metraje perdido)","n":"El corte entre dos planos crea significado","g":"Teoría del montaje","t":"Kuleshov, hacia 1920"},{"w":"El montaje de choque","gen":"Teoría de autor del cine","n":"Chocar dos planos produce un concepto nuevo","g":"Teoría del montaje","t":"Eisenstein, hacia 1929"},{"w":"El primer plano","gen":"Teoría de autor del cine","n":"El rostro revela una microfisonomía","g":"Teoría del cine mudo","t":"Balázs, 1924"},{"w":"La memoria oral","gen":"Obra de referencia","n":"El ritmo y la fórmula sostienen la memoria","g":"Psicología de la memoria","t":"Rubin, 1995"},{"w":"La superioridad de la imagen","gen":"Hallazgo replicado","n":"Lo que se ve se recuerda mejor","g":"Psicología de la memoria","t":"Paivio y Csapo, 1973"},{"w":"Contar sin la página","gen":"Herramienta de la etapa","n":"Tres casillas: de pie, en imagen, qué no se copia","g":"Storytelling de esta casa","t":"Etapa 11"},{"w":"El estatus mixto del efecto Kuleshov","gen":"Hallazgo con réplica discutida","n":"Réplica más débil, y apoyo neural distinto","g":"Psicología de la memoria","t":"Prince y Hensley, 1992; Mobbs y colegas, 2006"}];
