const explainQuestions=[{"q":"Explica la actio, según Quintiliano, «Institutio oratoria» (hacia el año 95 d.C.), y por qué contar de pie no es leer en voz alta.","ans":"Quintiliano describe, en «Institutio oratoria» (hacia el año 95 d.C.), la actio o pronuntiatio como la quinta parte de la retórica: la ejecución de pie de un discurso, con la voz y el gesto justos. La misma frase, dicha con la voz y el gesto correctos, convence; dicha sin ellos, se cae. Contar de pie no es leer en voz alta porque leer conserva un texto fijo, mientras que la actio exige presencia viva: pausa, mirada, tono, cuerpo, elementos que un texto leído de un papel casi siempre pierde, por bien leído que esté. Su límite es que es un tratado clásico de oratoria, pensado para el orador, no para todo relato."},{"q":"Explica el efecto Kuleshov (hacia 1920) y su estatus mixto, con la réplica de Prince y Hensley (1992) y el apoyo neural de Mobbs y colegas (2006).","ans":"El experimento Kuleshov, hacia 1918-1920, mostró que el mismo plano de un rostro inexpresivo, montado junto a un plato de sopa, un ataúd o una mujer, se lee como hambre, dolor o deseo: la cara no cambia, cambia lo que se puso al lado, y el significado nace del corte. Su estatus, sin embargo, es mixto: el metraje original se perdió y algunas versiones que circulan son reconstrucciones; y al intentar replicar el efecto en laboratorio, Prince y Hensley (1992) hallaron un resultado más débil de lo que contaba la leyenda del cine, mientras que trabajos posteriores con resonancia magnética, como el de Mobbs y colegas (2006), sí encontraron apoyo neural parcial para que el contexto cambie la lectura de un rostro. La regla de esta casa es enseñar el hallazgo con sus réplicas, no solo con su fama."},{"q":"Explica contar sin la página, la herramienta de esta etapa, y cómo se aplicaría a un video de siete minutos de la casa.","ans":"Contar sin la página tiene tres casillas: de pie (la voz y el cuerpo), preguntando qué gana esa parte si se cuenta en vivo, sin leer, con la pausa y el gesto justos (Quintiliano; Parry y Lord, 1960); en imagen (el plano y el corte), preguntando qué frase se puede tirar porque un plano concreto la muestra, y qué significan dos planos juntos que ninguno dice solo (Kuleshov; Eisenstein); y lo que NO se copia del texto, preguntando qué de lo escrito habría que rehacer para el oído o el ojo, en vez de trasladarlo tal cual. Aplicada a un video de siete minutos de la casa, exige repasar cada escena del guion con las tres preguntas antes de grabar: qué se cuenta de pie sin leer, qué frase se reemplaza por un plano, y qué parte del texto original tiene que rehacerse por completo."},{"q":"Explica la diferencia entre ilustrar la frase con un plano y sustituirla, según Balázs (1924), y por qué el montaje de Eisenstein (hacia 1929) no es solo unir planos.","ans":"Ilustrar la frase es filmar exactamente lo que la voz ya está diciendo, de modo que la imagen no aporta nada nuevo, solo repite; sustituirla, según Béla Balázs en «El hombre visible» (1924), es reemplazar la frase por un plano, casi siempre un primer plano, que revela una microfisonomía, algo que ninguna palabra alcanza a decir con la misma fuerza. El montaje de Eisenstein, hacia 1929, tras «El acorazado Potemkin» (1925), tampoco es solo unir planos en el orden en que ocurrieron: es chocar dos planos para producir un concepto nuevo que ninguno de los dos contiene por separado, lo que él llamó montaje intelectual. Su límite es que ese montaje intelectual puro pocas veces se logró en la práctica, y está en polémica con Bazin (visto en la etapa 4), que defendía el plano largo."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.',"<strong>Ejemplo:</strong> Chocar dos planos para producir un concepto nuevo. → <span style=\"color:var(--jade);font-weight:700;\">El montaje de choque (Eisenstein, hacia 1929)</span>"]);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
