const evalTFBank=[{"q":"La actio es la ejecución de pie de un discurso, con voz y gesto.","a":true},{"q":"Quintiliano describe la actio hacia el año 95 d.C.","a":true},{"q":"Contar de pie es leer un texto en voz alta, palabra por palabra.","a":false},{"q":"Según Parry y Lord (1960), el poeta oral compone en vivo con fórmulas.","a":true},{"q":"Walter Ong publicó «Oralidad y escritura» en 1982.","a":true},{"q":"El pensamiento oral, según Ong, es idéntico al pensamiento escrito.","a":false},{"q":"El experimento Kuleshov mostró que el corte entre dos planos crea significado.","a":true},{"q":"El metraje original del experimento Kuleshov se conserva completo y sin dudas.","a":false},{"q":"Eisenstein describe el montaje como choque, hacia 1929, tras «El acorazado Potemkin» (1925).","a":true},{"q":"Balázs publicó «El hombre visible» en 1924.","a":true},{"q":"El primer plano, según Balázs, no revela nada que la palabra no diga igual.","a":false},{"q":"David Rubin estudia la memoria oral en 1995.","a":true},{"q":"Según Paivio y Csapo (1973), lo que se ve se recuerda mejor que lo que se lee.","a":true},{"q":"El efecto Kuleshov se acepta hoy sin ninguna duda ni réplica.","a":false},{"q":"Contar sin la página tiene tres casillas: de pie, en imagen y qué no se copia.","a":true}];
const evalMCBank=[{"q":"Según Quintiliano, «Institutio oratoria» (hacia el 95 d.C.), ¿qué es la actio?","o":["a) Un texto que se memoriza y se recita igual siempre","b) La escritura de discursos, no su ejecución","c) La quinta parte de la retórica: la ejecución de pie, con la voz y el gesto justos","d) Un tipo de careo entre oradores"],"a":2},{"q":"Según Parry y Lord, «The Singer of Tales» (1960), ¿qué hace el poeta oral?","o":["a) Memoriza un texto fijo y lo repite palabra por palabra","b) Lee el poema de un manuscrito","c) Compone en vivo con fórmulas, cada vez distinto","d) Improvisa sin ninguna estructura"],"a":2},{"q":"¿Qué mostró el experimento Kuleshov (hacia 1918-1920)?","o":["a) Que el mismo plano de un rostro, montado junto a distintas imágenes, se lee de distinta manera","b) Que el sonido es más importante que la imagen","c) Que el primer plano no aporta nada","d) Que el montaje no cambia el significado de un plano"],"a":0},{"q":"¿Qué límite tiene el experimento Kuleshov, según esta etapa?","o":["a) El metraje original se perdió y algunas versiones son reconstrucciones","b) Nunca se hizo de verdad","c) Fue filmado a color","d) Lo hizo Eisenstein, no Kuleshov"],"a":0},{"q":"Según Eisenstein, ¿qué es el montaje como choque?","o":["a) Simplemente unir dos planos en orden","b) Filmar en un solo plano sin cortes","c) Una técnica exclusiva del sonido","d) Chocar dos planos para producir un concepto nuevo que ninguno contiene"],"a":3},{"q":"Según Béla Balázs, «El hombre visible» (1924), ¿qué revela el primer plano?","o":["a) Nada que la palabra no diga igual de bien","b) Una microfisonomía del rostro, algo que ninguna palabra alcanza a decir","c) Solo el vestuario del personaje","d) La voz interior narrada"],"a":1},{"q":"¿Cuáles son las tres casillas de «Contar sin la página»?","o":["a) Gancho, giro y cierre","b) ¿Qué de pie?, ¿qué en imagen?, ¿qué NO se copia del texto?","c) Título, música y duración","d) Presupuesto, elenco y locación"],"a":1},{"q":"¿Cuál es la grieta que esta etapa desarma?","o":["a) Creer que el cine no necesita guion","b) Creer que la oralidad ya no existe","c) Creer que el montaje es solo un adorno técnico","d) Creer que contar de pie es leer en voz alta, y que contar en imagen es filmar lo que dirías"],"a":3},{"q":"¿A qué ruta abre la puerta esta etapa, la undécima de la Ruta del Hilo que Tira?","o":["a) A la Ruta de la Cámara que Cuenta","b) A la Ruta del Expediente Real","c) A la Ruta de Personas de Papel","d) A la Ruta de la Pluma Afilada"],"a":0},{"q":"¿Qué defiende Ong (1982) sobre el pensamiento oral?","o":["a) Es idéntico al escrito","b) Es más aditivo, cercano a la vida y cargado de fórmulas y presencia","c) No existe fuera de la épica","d) Solo aplica a la poesía moderna"],"a":1},{"q":"¿Qué aporta Rubin (1995) sobre la memoria oral?","o":["a) La memoria oral es más débil que la escrita, siempre","b) La Odisea se escribió antes de contarse","c) El ritmo, la rima, las fórmulas y la imagen sostuvieron la Odisea sin escritura","d) La memoria no depende del ritmo"],"a":2},{"q":"¿Qué mide el efecto de superioridad de la imagen (Paivio y Csapo, 1973)?","o":["a) Que lo que se ve se recuerda mejor que lo que se lee","b) Que la imagen se recuerda peor que el texto","c) Que el sonido se recuerda mejor que la imagen","d) Que la memoria visual no existe"],"a":0},{"q":"¿Qué encontraron Prince y Hensley (1992) al intentar replicar el efecto Kuleshov?","o":["a) Un efecto más fuerte que la leyenda","b) Que el efecto no existe en absoluto","c) Un efecto más débil de lo que decía la leyenda","d) Que el sonido lo anula por completo"],"a":2},{"q":"¿Qué distingue la trampa que esta etapa desarma?","o":["a) Creer que la voz y la imagen son intercambiables sin cambios","b) Creer que el cine no necesita actores","c) Creer que la oratoria ya no se usa","d) Creer que contar de pie es leer en voz alta, y que contar en imagen es filmar lo que dirías"],"a":3},{"q":"¿Qué concede Eisenstein en la entrevista imaginada sobre su propio montaje intelectual?","o":["a) Que se logró siempre, sin excepción","b) Que casi nunca se logró del todo, ni en su propio cine","c) Que nunca lo intentó","d) Que lo abandonó antes de «Octubre»"],"a":1}];
const evalCPBank=[{"q":"Quintiliano describe la actio hacia el año ___.","a":"95"},{"q":"Parry y Lord publican «The Singer of Tales» en ___.","a":"1960"},{"q":"Ong publica «Oralidad y escritura» en ___.","a":"1982"},{"q":"El experimento Kuleshov ocurre hacia ___.","a":"1920"},{"q":"Eisenstein escribe sobre el montaje de choque hacia ___.","a":"1929"},{"q":"Balázs publica «El hombre visible» en ___.","a":"1924"},{"q":"Rubin estudia la memoria oral en ___.","a":"1995"},{"q":"Paivio y Csapo miden la superioridad de la imagen en ___.","a":"1973"},{"q":"Prince y Hensley replican el efecto Kuleshov en ___.","a":"1992"},{"q":"Contar sin la página tiene tres ___.","a":"casillas"},{"q":"La imagen no ilustra la frase, la ___ (Balázs, 1924).","a":"sustituye"},{"q":"El significado nace del ___ entre dos planos (Kuleshov).","a":"corte"},{"q":"Quintiliano llama ___ a la ejecución de pie.","a":"actio"},{"q":"El poeta oral ___ en vivo con fórmulas (Parry y Lord, 1960).","a":"compone"},{"q":"Esta etapa es la puerta a la Ruta de la Cámara que ___.","a":"Cuenta"}];
