function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"UN VIDEO CON VOZ EN OFF QUE LEE UN TEXTO SOBRE UNA IMAGEN QUE SOLO LO REPITE. Un video de M.E.T.A.S de L 40,000 pone una voz en off leyendo un párrafo entero, mientras la imagen muestra, plano a plano, exactamente lo que la voz ya va diciendo, sin aportar nada que la voz no haya dicho."},{"txt":"UNA PRESENTACIÓN DE SIETE MINUTOS QUE ALGUIEN PIENSA LEER DE UN PAPEL. Un maestro de M.E.T.A.S prepara una charla de L 15,000 en materiales, y piensa leerla completa de sus notas frente a los alumnos, palabra por palabra."},{"txt":"DOS PLANOS QUE, MONTADOS JUNTOS, DICEN ALGO QUE NINGUNO DICE SOLO. Un documental de L 90,000 sobre M.E.T.A.S tiene un plano de un alumno mirando un examen, y otro de una carta de aceptación a una beca; el editor duda si montarlos juntos o separarlos con una escena intermedia."},{"txt":"UN TESTIMONIO GRABADO QUE ALGUIEN QUIERE LEER DE UN GUION. Un alumno de M.E.T.A.S grabará un testimonio de L 20,000 en producción, y su primer borrador es un texto que piensa leer completo frente a la cámara, sin apartar la vista del papel."},{"txt":"UNA ESCENA FILMADA EN UN SOLO PLANO FRENTE A LA MISMA CORTADA. Una escena de L 70,000 en filmación se puede resolver en un solo plano largo, sin cortes, o cortada en varios planos que se monten después."},{"txt":"EL PRIMER PLANO DE UN ROSTRO QUE DICE MÁS QUE UN PÁRRAFO DE EXPLICACIÓN. Un video de L 18,000 sobre un logro de un alumno de M.E.T.A.S tiene un párrafo entero de voz en off explicando lo que sintió, cuando ya existe un primer plano de su rostro en el momento exacto."},{"txt":"UN CUENTO QUE LA ABUELA CONTABA DISTINTO CADA VEZ, Y QUÉ SE PIERDE AL FIJARLO POR ESCRITO. La familia de un alumno quiere transcribir, por L 10,000 en horas de trabajo, un cuento que la abuela contaba de memoria, distinto cada vez, para «dejarlo fijo para siempre»."},{"txt":"EL VIDEO DE SIETE MINUTOS DE LA CASA, REPASADO ANTES DE GRABAR. El guion del video insignia de M.E.T.A.S, de L 45,000 en producción, está listo para grabarse, pero nadie lo ha repasado todavía con la herramienta de esta etapa."}];
const critCaseQuestions=["1. Di si el problema de este caso está en que le falta ESTAR DE PIE (se lee en vez de contarse), en que la IMAGEN SOLO ILUSTRA (no sustituye ni corta), o en que se COPIÓ EL TEXTO tal cual, y por qué.","2. Aplica contar sin la página completo: ¿qué gana esta parte si se cuenta en vivo, sin leer?, ¿qué frase se puede tirar porque un plano la muestra, y qué dicen dos planos juntos?, ¿qué de lo escrito habría que rehacer?","3. Aplica una herramienta de la etapa (Quintiliano, Parry y Lord 1960, Ong 1982, Kuleshov hacia 1920, Eisenstein hacia 1929, o Balázs 1924) con su autor y su año.","4. Escribe la pregunta que decide y la condición con la que el caso quedaría resuelto."];
const critCaseGuides=["Se valora que se identifique con claridad si el problema real del caso es que falta contar de pie, que la imagen solo ilustra en vez de sustituir o cortar, o que se copió el texto tal cual, sin mezclar los tres en una sola respuesta vaga.","Se valora que las tres casillas de contar sin la página queden llenas con algo concreto del caso, o con la nota honesta de que alguna todavía no se puede llenar.","Se valora que la herramienta elegida encaje con el problema real del caso (una charla leída pide a Quintiliano o a Parry y Lord; un corte que debe significar pide a Kuleshov o a Eisenstein; una imagen que solo ilustra pide a Balázs) y que viaje con su autor y su año.","Se valora que la pregunta que decide sea concreta y que la condición diga con claridad qué cambiaría para que el caso quedara resuelto. No se valora cerrar con «ya se entiende así», que es justo la trampa que este caso desmiente."];
const critErrorBank=[{"txt":"«Leer el guion más fuerte y con pausas largas ya es contar de pie»","g1":"Confunde el volumen con la composición: contar de pie es componer en vivo, con fórmulas y presencia (Parry y Lord, 1960), no leer más despacio.","g2":"No aplica la primera casilla de contar sin la página: ¿qué gana esta parte si se cuenta en vivo, sin leer?"},{"txt":"«Si la imagen muestra lo mismo que dice la voz en off, la escena ya está bien resuelta»","g1":"Confunde ilustrar con sustituir: la imagen tiene que reemplazar la frase, no repetirla (Balázs, 1924).","g2":"No aplica la segunda casilla: qué frase se puede tirar porque el plano ya la muestra."},{"txt":"«El efecto Kuleshov demuestra, sin ninguna duda, que cualquier corte genera significado»","g1":"Ignora el estatus mixto del hallazgo: Prince y Hensley (1992) hallaron un efecto más débil que la leyenda.","g2":"No distingue una afirmación replicada de una discutida."},{"txt":"«El montaje de Eisenstein es solo pegar planos en el orden correcto»","g1":"Confunde unir con chocar: el montaje de choque produce un concepto nuevo que ninguno de los dos planos contiene (Eisenstein, hacia 1929).","g2":"No aplica la lógica de que el corte produce un concepto nuevo, no solo un orden."},{"txt":"«La actio de Quintiliano es un manual moderno de oratoria política»","g1":"Le falta la fecha correcta: es un tratado clásico, hacia el año 95 d.C., no un manual contemporáneo.","g2":"No distingue un tratado clásico de un manual moderno."},{"txt":"«La imagen siempre gana; ya no hace falta contar nada de pie»","g1":"Ignora que cada medio hace un trabajo distinto (Ong, 1982): la palabra encadena lo abstracto y la causa mejor que ningún plano.","g2":"No aplica la tercera casilla: qué de lo escrito habría que rehacer, en vez de descartarlo todo."}];
const critDecisionBank=["El video de L 40,000 ya tiene la voz en off leyendo sobre una imagen que solo repite: ¿se cambian los planos por otros que sustituyan frases enteras, se deja como está porque «ya se entiende», o se quita la voz en off por completo? Di qué harías.","La charla de L 15,000 en materiales ya está escrita para leerse completa: ¿se convierte en fichas con las ideas, para contarla de pie, se deja para leerla igual porque «así no se equivoca», o se graba antes y se reproduce en el salón? Di el efecto de cada opción.","El documental de L 90,000 tiene los dos planos, del examen y de la carta de la beca: ¿se montan juntos, uno tras otro, se separan con una escena intermedia que explique la conexión, o se filma un tercer plano que una las dos ideas? Di qué elegirías y por qué.","El testimonio de L 20,000 en producción ya tiene un guion completo para leer: ¿se convierte en una historia contada de pie, con pausas y sin papel, se deja leído porque «se ve más prolijo», o se graba dos veces, leído y de pie, para comparar? Di qué harías.","La escena de L 70,000 en filmación se puede resolver en un plano largo o cortada en varios: ¿qué se decide, y con qué criterio (busca un significado que solo nazca del corte, o el plano largo ya cuenta lo que hace falta)? Di tu decisión y su condición.","El video de L 18,000 tiene el párrafo explicativo y el primer plano disponible: ¿se deja solo el primer plano, sin la voz en off, se dejan los dos juntos, o se quita el primer plano y se deja solo la explicación? Di qué harías, con Balázs (1924) de por medio.","La familia ya decidió fijar el cuento de la abuela por escrito, con L 10,000 en horas de trabajo: ¿se transcribe una sola versión y se pierde la variación, se graban varias versiones en audio y video para conservar la composición en vivo, o se hacen las dos cosas? Di qué harías, con Parry y Lord (1960) de por medio.","El guion de L 45,000 en producción está listo para grabarse sin repasar: ¿se aplican las tres casillas de contar sin la página antes de grabar, se graba igual porque «ya está bien escrito», o se repasa solo la mitad por falta de tiempo? Di qué harías y qué se arriesga si no se repasa."];
const critDecisionGuide="La decisión se puntúa por el procedimiento con que se llegó a ella, no por lo audaz que suene. Se valora que se identifique si el problema real está en que falta contar de pie (se lee en vez de componerse en vivo), en que la imagen solo ilustra en vez de sustituir, o en que no se buscó el corte que significa, y que la herramienta elegida (Quintiliano, Parry y Lord, Ong, Kuleshov, Eisenstein o Balázs) encaje con el problema real y viaje con su autor y su año. Se valora que la respuesta no se cierre filmando exactamente lo que se diría, o leyendo el guion en voz alta, que es justo la trampa que esta etapa desarma. Se valora la honradez cuando el caso, tal como está descrito, no permite decidir con los datos que hay: decir «falta este dato» es una respuesta correcta.";
const critCompareBank=[{"a":"«El video pone una voz en off leyendo el texto completo, mientras la imagen repite exactamente lo dicho.»","b":"«El video reemplaza la mitad de las frases por planos que las sustituyen, y deja solo la voz para lo que la imagen no puede mostrar.»","ga":"Ilustra en vez de sustituir: la imagen no aporta nada nuevo (Balázs, 1924).","gb":"Aplica la segunda casilla de contar sin la página: la imagen sustituye la frase.","gr":"Los dos videos cuentan lo mismo. La diferencia es si la imagen sustituye o solo ilustra."},{"a":"«El maestro lee su charla de siete minutos de un papel, sin levantar la vista.»","b":"«El maestro cuenta la misma charla de pie, con fichas de apoyo, pausas y gesto.»","ga":"Es leer en voz alta, no contar de pie: falta la actio (Quintiliano).","gb":"Cumple la actio y la composición oral (Parry y Lord, 1960).","gr":"Los dos usan las mismas ideas. La diferencia es si se leen o se componen en vivo."},{"a":"«Los dos planos, el del examen y el de la carta de la beca, se filman por separado y nunca se montan juntos.»","b":"«Los dos planos se montan uno después del otro, sin ninguna explicación de por medio.»","ga":"Pierde el significado que solo nace del corte (Kuleshov, hacia 1920).","gb":"Aplica el efecto Kuleshov: el corte entre los dos planos dice lo que ninguno dice solo.","gr":"Los dos documentales tienen el mismo material. La diferencia es si se monta el corte que significa."},{"a":"«El cuento de la abuela se transcribe una sola vez, y esa versión queda como la única, fija para siempre.»","b":"«El cuento de la abuela se graba en varias sesiones, distinto cada vez, y se conservan las variaciones.»","ga":"Trata la composición oral como si fuera un texto fijo, perdiendo lo que Parry y Lord (1960) describen.","gb":"Respeta la lógica oral: compone distinto cada vez (Parry y Lord, 1960; Ong, 1982).","gr":"Los dos parten del mismo cuento. La diferencia es si se fija como texto único o se conserva como composición viva."}];
const critCauseBank=[{"cause":"Un video pone una voz en off leyendo un texto mientras la imagen repite exactamente lo dicho.","guide":"Ilustra en vez de sustituir (Balázs, 1924). Se corrige cambiando planos por otros que reemplacen frases enteras."},{"cause":"Una charla de siete minutos se prepara para leerse completa de un papel.","guide":"No aplica la actio (Quintiliano): falta la voz, la pausa y el gesto de pie. Se corrige convirtiéndola en fichas con las ideas."},{"cause":"Dos planos con potencial de significado se filman pero nunca se montan juntos.","guide":"Pierde el efecto Kuleshov (hacia 1920): el significado nace del corte. Se corrige montando los dos planos en secuencia."},{"cause":"Un cuento oral de la familia se transcribe una sola vez y se declara fijo para siempre.","guide":"Trata la composición oral como texto fijo (Parry y Lord, 1960). Se corrige grabando varias versiones distintas."},{"cause":"Un guion de siete minutos está listo para grabarse sin repasar con contar sin la página.","guide":"Salta el protocolo de la etapa. Se corrige aplicando las tres casillas antes de grabar."},{"cause":"Un editor pega dos planos en orden cronológico sin buscar qué dicen juntos.","guide":"Confunde unir con chocar (Eisenstein, hacia 1929). Se corrige buscando el corte que produzca un concepto nuevo."}];
const critEffectBank=[{"effect":"El video cambia la mitad de sus frases por planos que las sustituyen, y deja la voz solo para lo que la imagen no puede mostrar.","guide":"Se aplicó la segunda casilla de contar sin la página: la imagen sustituye la frase, no la ilustra."},{"effect":"La charla se cuenta de pie, con fichas de apoyo, pausas y gesto, sin leer una sola línea completa.","guide":"Se aplicó la actio (Quintiliano) y la composición oral (Parry y Lord, 1960)."},{"effect":"Los dos planos, del examen y de la carta de la beca, se montan uno después del otro, y juntos dicen algo que ninguno decía solo.","guide":"Se aplicó el efecto Kuleshov (hacia 1920): el corte crea el significado."},{"effect":"El cuento de la abuela se graba en varias sesiones, y se conservan las distintas versiones que cuenta cada vez.","guide":"Se respetó la lógica de la composición oral (Parry y Lord, 1960; Ong, 1982)."},{"effect":"El guion de siete minutos se repasa con las tres casillas de contar sin la página antes de grabar.","guide":"Se corrió el protocolo completo de esta etapa antes de comprometer la producción."},{"effect":"El editor busca, entre los planos disponibles, dos que al chocar produzcan un concepto que ninguno tenía por separado.","guide":"Se aplicó el montaje de choque (Eisenstein, hacia 1929), no solo unir planos."}];
function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🎥 Contar sin la página bajo presión · Forma ${cf} · Contar de pie y contar en imagen · Ruta del Hilo que Tira`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El caso sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">Aplica contar sin la página a este caso: ¿qué de pie?, ¿qué en imagen?, ¿qué NO se copia del texto?, y qué herramienta (con su autor y su año) usarías.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🎥 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Contar sin la página bajo presión: '+total+'/100');}
  else showToast('🎥 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El caso sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">Aplica contar sin la página a este caso: ¿qué de pie?, ¿qué en imagen?, ¿qué NO se copia del texto?, y qué herramienta (con su autor y su año) usarías.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. El caso</div>`+critCaseQuestions.map((q,i)=>`<div class="p-crit-line">${q} ${critCaseGuides[i]}</div>`).join('')+`</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Contar sin la página bajo presión · Contar de pie y contar en imagen · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #a21caf;background:#fae8ff;color:#701a75;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#a21caf;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #a21caf;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#fae8ff;border-left:3px solid #a21caf;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#fae8ff;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#fae8ff;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#a21caf;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #a21caf;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Contar sin la página bajo presión · Contar de pie y contar en imagen · Ruta del Hilo que Tira · Etapa 11</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Contar sin la página bajo presión · Contar de pie y contar en imagen · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"hacia el 95 d.C.","icon":"🎭","label":"Quintiliano y la actio","text":"Quintiliano escribe «Institutio oratoria», con la actio o pronuntiatio, la quinta parte de la retórica: la ejecución de pie, con la voz y el gesto justos. <strong>Por qué importa aquí:</strong> es la fuente más antigua de la etapa, y fija que la misma frase dicha con voz y gesto convence, y dicha sin ellos se cae."},{"y":"hacia 1920","icon":"🎬","label":"Kuleshov y el efecto que lleva su nombre","text":"Lev Kuleshov monta el mismo plano de un rostro inexpresivo junto a distintas imágenes, y el público lee hambre, dolor o deseo según lo que está al lado. <strong>Por qué importa aquí:</strong> fija que el significado nace del corte, no del plano solo; el metraje original se perdió, y el principio se ha seguido estudiando después."},{"y":"1924","icon":"🎥","label":"Balázs y el primer plano","text":"Béla Balázs publica «El hombre visible» (Der sichtbare Mensch): el cine devuelve una cultura visual, y el primer plano de un rostro revela una microfisonomía que ninguna palabra alcanza a decir. <strong>Por qué importa aquí:</strong> es la fuente que declara que la imagen sustituye a la frase, no la ilustra."},{"y":"hacia 1929","icon":"🎞️","label":"Eisenstein y el montaje de choque","text":"Serguéi Eisenstein, tras «El acorazado Potemkin» (1925), escribe sobre el montaje como choque: montar es chocar dos planos para producir un concepto nuevo que ninguno contiene. <strong>Por qué importa aquí:</strong> es la teoría que lleva el efecto Kuleshov a su forma más ambiciosa, el montaje intelectual."},{"y":"1960","icon":"🎤","label":"Parry y Lord y la composición oral","text":"Milman Parry y Albert Lord publican «The Singer of Tales»: el poeta oral no memoriza un texto fijo, lo compone en vivo con fórmulas, cada vez distinto. <strong>Por qué importa aquí:</strong> fija que contar de pie es componer, no recitar."},{"y":"1982","icon":"🗣️","label":"Ong y la oralidad","text":"Walter Ong publica «Oralidad y escritura» (Orality and Literacy): el pensamiento oral tiene su propia lógica, más aditiva y cercana a la vida que la escrita. <strong>Por qué importa aquí:</strong> explica por qué contar de pie usa una gramática distinta de la de la página."},{"y":"1995","icon":"🧠","label":"Rubin y la memoria oral","text":"David Rubin publica «Memory in Oral Traditions»: el ritmo, la rima, las fórmulas y la imagen son las muletas que dejaron sobrevivir siglos a la Odisea sin escritura. <strong>Por qué importa aquí:</strong> conecta la composición oral con cómo funciona de verdad la memoria humana."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: EL VIDEO CON VOZ EN OFF QUE LEE, Y LA IMAGEN QUE SOLO REPITE ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(seAplicaHerramienta){sfx(seAplicaHerramienta?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(seAplicaHerramienta){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎥</span><span class="ms-text"><strong>Se aplicó contar sin la página:</strong> se cambió la mitad de las frases por planos que las sustituían, y la charla del maestro se armó de pie, con fichas, sin leer una sola línea completa.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Quedó apuntada la razón del cambio:</strong> «que se entienda no basta: hay que rehacer, no copiar», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📖</span><span class="ms-text"><strong>Se grabó tal cual:</strong> el guion se leyó completo y la imagen siguió repitiendo lo que la voz decía, y cuando alguien preguntó por qué el video se sentía plano, nadie en la casa supo qué responder.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🎥</span><span class="ms-text"><strong>Confundir «se entiende» con «se contó de pie o en imagen»</strong> es exactamente el error que esta etapa señala: lo que distingue contar de leer o ilustrar no es si el mensaje llega, es si se compuso en vivo o se sustituyó de verdad la frase por un plano.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

