// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = Contar de pie (la voz y el cuerpo),
// paradoja = Contar en imagen (el plano y el corte), utilidad = Contar sin
// la página, ruina = Leer en voz alta o ilustrar la frase.
const parteData={"esperado":{"nombre":"Contar de pie (la voz y el cuerpo)","icon":"🧍","estructura":{"title":"Qué es","info":"• Componer en vivo con la voz, la pausa y el gesto, sin leer<br>• Es la actio de Quintiliano (hacia 95 d.C.) y la composición oral de Parry y Lord (1960)<br>• La historia de siete minutos que se sostiene sin papel<br>• NO es lo mismo que leer un texto en voz alta, aunque se lea con energía"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿la voz, la pausa y el gesto sostienen la historia sin papel?<br>• Se compara con contar sin la página: ¿qué gana esta parte si se cuenta en vivo?<br>• Se busca si compone distinto cada vez, o recita un texto fijo (Parry y Lord, 1960)<br>• Se anota en la primera casilla de la herramienta"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que leer más fuerte, o con más pausas, ya es contar de pie<br>• En memorizar un texto fijo y llamarlo composición oral<br>• En usar la actio (Quintiliano) sin la pausa ni el gesto, solo la voz<br>• En olvidar la lógica oral que describe Ong (1982)"},"cuidados":{"title":"En esta casa","info":"• Todo video de siete minutos de esta casa se prueba contado de pie antes de grabarse<br>• Se declara siempre «Quintiliano, hacia 95 d.C.» al citar la actio<br>• Se usa como primer movimiento de contar sin la página<br>• Y se recuerda que contar de pie bien hecho no necesita leer nada"}},"paradoja":{"nombre":"Contar en imagen (el plano y el corte)","icon":"🎬","estructura":{"title":"Qué es","info":"• La imagen que sustituye a la frase, y el montaje que significa<br>• Balázs (1924): el primer plano revela una microfisonomía<br>• Kuleshov (hacia 1920) y Eisenstein (hacia 1929): el significado nace del corte<br>• NO es lo mismo que filmar exactamente lo que se diría"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué frase se puede tirar porque un plano concreto la muestra?<br>• Se busca qué dicen dos planos juntos que ninguno dice solo<br>• Se compara con contar sin la página, segunda casilla<br>• Se comprueba si el montaje choca ideas, o solo une planos"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que filmar la frase ya es contar en imagen<br>• En pegar planos sin buscar qué dice el corte<br>• En usar un primer plano sin que revele nada nuevo<br>• En confiar en un efecto Kuleshov sin su estatus mixto (Prince y Hensley, 1992)"},"cuidados":{"title":"En esta casa","info":"• Todo guion de esta casa busca al menos un corte que signifique, antes de filmar<br>• Se declara siempre el año al citar Kuleshov, Eisenstein o Balázs<br>• Se usa como segundo movimiento de contar sin la página<br>• Y se recuerda que la imagen sustituye, no ilustra"}},"utilidad":{"nombre":"Contar sin la página","icon":"📋","estructura":{"title":"Qué es","info":"• La herramienta de esta etapa, en tres casillas: ¿qué de pie?, ¿qué en imagen?, ¿qué NO se copia del texto?<br>• Se apoya en las seis herramientas de la tabla madre, cada una con su autor y su año<br>• Se recuerda con Rubin (1995) y Paivio y Csapo (1973): la memoria oral y la visual son distintas<br>• Si no aguanta las tres casillas, todavía no está lista para grabarse"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta qué gana esta parte si se cuenta en vivo, sin leer<br>• Se busca qué frase se puede tirar porque un plano la muestra<br>• Se comprueba qué de lo escrito habría que rehacer, en vez de copiarlo<br>• Se anota en las tres casillas, aunque a veces una quede pendiente"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que basta con una de las tres casillas llena<br>• En copiar el texto tal cual, sin rehacerlo para el oído o el ojo<br>• En dejar una casilla sin llenar, y fingir que la herramienta cerró igual<br>• En olvidar que de pie y en imagen piden gramáticas distintas"},"cuidados":{"title":"En esta casa","info":"• Todo relato de esta casa que sale de la página se mide con las tres casillas<br>• Se declara siempre la herramienta que sostiene cada decisión<br>• Se usa como la prueba final antes de grabar cualquier video<br>• Y se recuerda que ninguna casilla se salta"}},"ruina":{"nombre":"Leer en voz alta o ilustrar la frase","icon":"🚫","estructura":{"title":"Qué es","info":"• Leer un texto en voz alta y llamarlo contar de pie; filmar una imagen que solo repite lo que la voz ya dijo<br>• Es donde caen los videos de la casa que ponen una voz en off leyendo, con la imagen solo ilustrando<br>• No es lo mismo que usar la actio (Quintiliano) o el primer plano (Balázs, 1924) de verdad<br>• Es la otra cara de contar sin la página: donde el oficio termina y la copia empieza"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿esto se sostiene de pie, sin leer, o es un texto disfrazado de discurso?<br>• Se pregunta: ¿esta imagen sustituye una frase, o solo la repite?<br>• Se compara con contar sin la página: ¿qué se copió tal cual, sin rehacer?<br>• Se decide si el video se cae, o aguanta, al pedir el corte que signifique"},"enfermedades":{"title":"Dónde se cae","info":"• En leer el guion completo, aunque sea con buena voz<br>• En filmar exactamente la frase que se diría, sin sustituirla<br>• En confiar en una voz en off que hace todo el trabajo<br>• En olvidar que cada medio tiene su propia gramática"},"cuidados":{"title":"En esta casa","info":"• Todo guion sospechoso, en esta casa, se revisa antes de grabarse<br>• Se pregunta siempre: ¿qué de esto se rehizo para el oído o el ojo?<br>• Se prefiere grabar de nuevo que dejar un texto disfrazado de discurso<br>• Y se recuerda: lo que funciona en la página se rehace, no se copia"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

